import json
source = '''def audit(events, at):
    selected = {}
    for event in events:
        if event['seen'] > at:
            continue
        key = event['key']
        rev = event['rev']
        pair = (event['state'], event['stamp'])
        if key not in selected or rev > selected[key][0]:
            selected[key] = (rev, {pair})
        elif rev == selected[key][0]:
            selected[key][1].add(pair)
    result = {}
    for key, (_, pairs) in selected.items():
        if len(pairs) != 1:
            result[key] = 'conflict'
        else:
            state, stamp = next(iter(pairs))
            result[key] = 'stale' if at - stamp > 6 else state
    return result
'''
events = [{"kind":"obs","key":"alder","rev":2,"state":"arrived","stamp":14,"seen":15},{"kind":"obs","key":"alder","rev":2,"state":"missed","stamp":14,"seen":19},{"kind":"obs","key":"balsa","rev":4,"state":"missed","stamp":13,"seen":20},{"kind":"obs","key":"cedar","rev":2,"state":"arrived","stamp":14,"seen":16},{"kind":"obs","key":"cedar","rev":1,"state":"missed","stamp":18,"seen":18},{"kind":"obs","key":"dune","rev":1,"state":"arrived","stamp":19,"seen":21},{"kind":"obs","key":"alder","rev":2,"state":"arrived","stamp":14,"seen":15},{"kind":"obs","key":"balsa","rev":5,"state":"arrived","stamp":19,"seen":30}]
ce = {'events': [{'kind':'obs','key':'x','rev':1,'state':'arrived','stamp':14,'seen':15}, {'kind':'obs','key':'x','rev':1,'state':'missed','stamp':14,'seen':19}], 'at':20, 'expected':{'x':'conflict'}}
artifact = {'source':source, 'result':{'alder':'conflict','balsa':'stale','cedar':'arrived'}, 'counterexample':ce}
payload = json.dumps(artifact)
recovered = json.loads(payload)
namespace = {}
exec(recovered['source'], namespace)
audit = namespace['audit']
before = json.dumps(events)
assert audit(events,20) == recovered['result']
assert json.dumps(events) == before
assert audit(ce['events'],ce['at']) == recovered['counterexample']['expected']
def faulty(events, at):
    selected = {}
    for event in events:
        if event['seen'] <= at and (event['key'] not in selected or event['rev'] >= selected[event['key']]['rev']):
